#include <stdio.h>
#include <stdlib.h>

int bestRotation(int* nums, int n) {
    int* change = (int*)malloc((size_t)n * sizeof(int));
    if (!change) return 0;
    for (int i = 0; i < n; i++) change[i] = 1;
    for (int i = 0; i < n; i++) {
        int start = (i - nums[i] + 1) % n;
        if (start < 0) start += n;
        change[start]--;
    }
    for (int i = 1; i < n; i++) change[i] += change[i - 1];
    int best = 0;
    for (int i = 1; i < n; i++) if (change[i] > change[best]) best = i;
    free(change);
    return best;
}

